import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"文件系统抽象","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/file-system.md","filePath":"zh-Hans/deep-dive/file-system.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/file-system.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="文件系统抽象" tabindex="-1">文件系统抽象 <a class="header-anchor" href="#文件系统抽象" aria-label="Permalink to “文件系统抽象”">​</a></h1><p>插件把文件系统接口抽象为统一的文件系统类 <code>RootFs</code>，定义于 <code>packages/plugin/src/fs/interface.ts</code>。所有抽象都设计为在每次同步运行中不可变、可抛弃。</p><p>不同类型的<a href="./file-system-wrappers">包装器</a>可以叠加在统一接口之上。它们的存在让文件系统功能可以轻松扩展。原始 FS 类不应携带任何附加功能，例如基目录配置或重试，这些都应通过包装器实现。</p><h2 id="vault-抽象" tabindex="-1">Vault 抽象 <a class="header-anchor" href="#vault-抽象" aria-label="Permalink to “Vault 抽象”">​</a></h2><p>Vault 文件系统消费 <a href="./request#vault-request"><code>VaultRequest</code></a>，一个抽象 Obsidian vault API 的带类型操作函数。</p><p><code>constructor()</code>：接收一个 <code>VaultRequest</code> 和仓库名称。</p><p><code>getUid()</code>：返回 <code>obsidian-vault~&lt;vault-name&gt;</code>。</p><p><code>read()</code>：委托给 <code>VaultRequest</code> 的 <code>GET</code>，它包装 <code>vault.adapter.readBinary()</code> 并把结果转换为 <code>Binary</code>。</p><p><code>readStream()</code>：委托给 <code>GET_STREAM</code>，使用提供的 stat 中的文件大小。<code>size</code> 在没有本地文件流支持的平台上启用基于范围的流式传输，见<a href="./request#vault-request">请求</a>。</p><p><code>write()</code>：委托给 <code>PUT</code>，把文件 <code>meta</code> 中的 <code>ctime</code> 和 <code>mtime</code> 作为 Obsidian <code>DataWriteOptions</code> 传入，然后调用 <code>this.stat()</code> 并返回文件 UID。</p><p><code>writeStream()</code>：</p><ul><li>创建 <code>.trash/&lt;random-UUID&gt;.part</code>，需要时先创建 <code>.trash</code></li><li>读取输入流，用 <code>APPEND</code> 追加每个分块，并把文件 <code>meta</code> 中的 <code>ctime</code> 和 <code>mtime</code> 作为 <code>DataWriteOptions</code> 传入</li><li>移除已存在的目标，然后把临时文件移动到位</li><li>调用 <code>this.stat()</code> 并返回文件 UID</li><li>失败时取消输入流，并永久删除临时文件</li></ul><p><code>delete()</code>：委托给 <code>DELETE</code>，遵循用户的垃圾桶选项。<code>vault.config.trashOption: &quot;none&quot;</code> 调用 <code>vault.adapter.remove()</code> 做永久删除。<code>&quot;local&quot;</code> 直接调用 <code>trashLocal()</code>；<code>&quot;system&quot;</code> 或未设置时先尝试 <code>trashSystem()</code>，需要时回退到 <code>trashLocal()</code>。</p><p><code>move()</code>：委托给 <code>MOVE</code>，在规范化目标路径后包装 <code>vault.adapter.rename()</code>。</p><p><code>mkdir()</code>：委托给 <code>MKDIR</code>，包装 <code>vault.adapter.mkdir()</code>。创建根目录是无操作。</p><p><code>stat()</code>：</p><ul><li>委托给 <code>STAT</code></li><li><code>workspace.layoutReady</code> 时使用缓存的 <code>TFile</code>/<code>TFolder</code> 元数据；否则回退到 <code>vault.adapter.stat()</code></li><li>把文件结果转换为项目的 <code>Stat</code> 格式，<code>uid</code> 为 <code>mtime</code> + <code>size</code> 用 <code>~</code> 分隔，<code>meta</code> 以字符串返回 <code>ctime</code> 和 <code>mtime</code>；文件夹没有 UID</li></ul><p><code>list()</code>：以并发请求递归遍历后代。<code>LIST</code> 在布局就绪时使用缓存的文件夹子项，否则用 <code>vault.adapter.list()</code>。每个文件随后经过 <code>stat()</code>，文件夹条目直接返回。被查询的根目录不包含在结果中。</p><p><code>exists()</code>：先检查 <code>vault.getAbstractFileByPath()</code>，然后回退到 <code>vault.adapter.exists(path, true)</code>。</p><h2 id="统一键模式" tabindex="-1">统一键模式 <a class="header-anchor" href="#统一键模式" aria-label="Permalink to “统一键模式”">​</a></h2><p>所有抽象文件系统都应自动在统一键和它们的原生文件路径之间转换：</p><ul><li><code>/</code> 是根目录。</li><li>文件没有尾部斜杠。</li><li>文件夹有尾部斜杠。</li><li>非根路径没有前导斜杠。</li></ul><p>例如：</p><ul><li>根目录：<code>/</code></li><li><code>file.md</code>、<code>folder/file.md</code> 表示文件。</li><li><code>folder/</code>、<code>folder/folder/</code> 表示文件夹。</li></ul><h2 id="优化器" tabindex="-1">优化器 <a class="header-anchor" href="#优化器" aria-label="Permalink to “优化器”">​</a></h2><p>执行期间，本地和远端文件系统使用优化包装器。它们批量收集修改调用并调用第一个已注册的优化器；批量与依赖处理记录在<a href="./file-system-wrappers#optimization-wrapper">优化包装器</a>。</p><p>流程把任务排序为文件删除、目录创建、移动、目录删除和剩余操作，然后并发执行优化后的任务列表。运行报告 <code>completed</code>、<code>failed</code>、<code>cancelled</code> 或 <code>noop</code>。</p>`,27)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};